import { before, describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

import { loadSpeechGate, samplesOf, type SpeechGate } from "../src/speech-gate.js";
import { parseWavAudio } from "../src/protocol/wav.js";

/**
 * The pinned model, and what it says about the signals this bridge meets.
 *
 * The fixture is a TTS utterance generated by this deployment's own gateway — not a
 * person's voice — and white noise stands in for the broadband non-speech the pilot's
 * boards hear. Measured 2026-11-03: silence 0.044, white noise 0.113, a 440 Hz tone
 * 0.013, the fixture 0.999. The default threshold of 0.5 sits in the gap.
 */

const MODEL = new URL("../models/vad/silero_vad.onnx", import.meta.url);
const CHECKSUM = new URL("../models/vad/silero_vad.onnx.sha256", import.meta.url);
const FIXTURE = new URL("./fixtures/speech-16k.wav", import.meta.url);

let gate: SpeechGate;

before(async () => {
  const loaded = await loadSpeechGate(MODEL, CHECKSUM);
  assert.ok(loaded, "the vendored model loads and its checksum matches");
  gate = loaded;
});

const speech = () => samplesOf(parseWavAudio(readFileSync(FIXTURE)).pcm);
const noise = () =>
  Int16Array.from({ length: 24_000 }, () => Math.round((Math.random() * 2 - 1) * 8000));

describe("the speech gate", () => {
  it("counts a person's utterance as many speech frames", async () => {
    const score = await gate.score(speech(), 0.5);
    assert.ok(score.max > 0.5, `max ${score.max} should clear the default threshold`);
    assert.ok(score.strong > 20, `${score.strong} frames should be speech, not just a peak`);
    assert.ok(score.frames > score.strong);
  });

  it("counts white noise, silence and a tone as no speech frames", async () => {
    const tone = Int16Array.from({ length: 24_000 }, (_, i) =>
      Math.round(12000 * Math.sin((2 * Math.PI * 220 * i) / 16000))
    );
    for (const [name, samples] of [
      ["white noise", noise()],
      ["silence", new Int16Array(24_000)],
      ["a 220 Hz tone", tone],
    ] as const) {
      const score = await gate.score(samples, 0.5);
      assert.equal(score.strong, 0, `${name} is not speech`);
    }
  });

  it("refuses a model whose bytes do not match its checksum", async () => {
    const modelPath = join(tmpdir(), `silero-${process.pid}.onnx`);
    const checksumPath = join(tmpdir(), `silero-${process.pid}.sha256`);
    writeFileSync(modelPath, readFileSync(MODEL));
    writeFileSync(checksumPath, `${"0".repeat(64)}  silero_vad.onnx\n`);

    assert.equal(
      await loadSpeechGate(pathToFileURL(modelPath), pathToFileURL(checksumPath)),
      null
    );
  });

  it("passes turns through when the model is missing", async () => {
    const missing = pathToFileURL(join(tmpdir(), `absent-${process.pid}.onnx`));
    assert.equal(await loadSpeechGate(missing, CHECKSUM), null);
  });
});
